do $seed_question_first_content_v5$
declare
  v_catalog_id uuid;
  v_skill_id uuid;
  v_lesson_id uuid;
  v_set_id uuid;
  v_question_id uuid;
  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'CHEMISTRY_REACTION_EVIDENCE';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 14, 'Evidências: o que os dados permitem concluir', 'Bolhas, cor, temperatura e sólidos são observações úteis, mas uma pista isolada pode ter causas físicas. Compare controles, investigue produtos e delimite a conclusão.', '## Comece pelo que foi observado
Registre sem interpretar: surgiu gás, apareceu um sólido, a cor mudou, a temperatura variou ou houve mudança de estado? Em seguida, pergunte se alguma substância nova foi formada. Uma transformação química envolve reagentes que dão origem a produtos com composição ou identidade diferente.

## Uma pista não é uma prova isolada
Bolhas podem resultar de ebulição ou da saída de gás já dissolvido; uma cor pode mudar porque pigmentos se misturaram ou porque um indicador respondeu ao pH; a temperatura pode variar durante dissolução ou cristalização. Essas observações orientam uma hipótese, mas devem ser comparadas a outras explicações.

## Compare e controle
Teste cada reagente isoladamente nas mesmas condições e compare com a mistura. Mantenha volumes, recipiente, temperatura e iluminação constantes, quando forem relevantes. Repita observações e procure propriedades de produtos diferentes dos reagentes. Um sólido que aparece apenas na mistura e apresenta propriedades próprias sustenta a hipótese de precipitação.

## Explique no nível das partículas
Em uma reação, os átomos dos reagentes se reorganizam e formam substâncias diferentes; os átomos não desaparecem. Em um sistema fechado, a massa total se conserva. Em um recipiente aberto, uma leitura pode diminuir se um gás sair: isso muda a fronteira do que a balança está medindo, não a quantidade total de matéria.

## Exemplo resolvido
Duas soluções transparentes são misturadas e surge um sólido branco. Controles de cada solução, preparados e mantidos nas mesmas condições, continuam transparentes. Uma análise adicional mostra que o sólido tem propriedades diferentes das soluções iniciais. A combinação de controle, produto distinto e observação reproduzível sustenta a conclusão de que ocorreu uma transformação química. Se o único dado fossem bolhas em um líquido aquecido, ebulição continuaria sendo uma explicação possível.',
    'Em três recipientes iguais, a solução A fica sozinha, a solução B fica sozinha e A+B são misturadas. Apenas A+B forma um sólido. A observação é “surgiu um sólido”; a inferência é “pode ter se formado um produto insolúvel”. Controles iguais e uma comparação das propriedades do sólido com as dos reagentes tornam a inferência mais forte. A conclusão não deve ir além dos dados coletados.', array['Escreva primeiro a observação e depois a inferência.', 'Pergunte quais explicações físicas também poderiam produzir o sinal.', 'Compare a mistura com controles nas mesmas condições.', 'Procure propriedades ou composição de produtos diferentes dos reagentes.', 'Defina a fronteira do sistema antes de interpretar massa medida.']::text[], 22, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v14-chemistry-reaction-evidence","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Reconhecer estados físicos e propriedades observáveis.","Distinguir observação, hipótese e conclusão.","Ler tabelas simples de comparação entre amostras."],"key_concepts":["mudança física e identidade da substância","formação de novas substâncias por reorganização de átomos","gás, precipitado, cor e temperatura como evidências contextualizadas","controle experimental e explicações alternativas","conservação da matéria em sistema fechado"],"progression":[{"stage":"FOUNDATION","focus":"Separar observação de inferência e reconhecer mudanças físicas.","questionIds":["v5-chem-reaction-evidence-probe-01","v5-chem-reaction-evidence-probe-02"]},{"stage":"APPLICATION","focus":"Interpretar evidências em situações controladas e comparáveis.","questionIds":["v5-chem-reaction-evidence-practice-01","v5-chem-reaction-evidence-practice-02","v5-chem-reaction-evidence-practice-03"]},{"stage":"TRANSFER","focus":"Aplicar o raciocínio a processos biológicos, ambientais e cotidianos.","questionIds":["v5-chem-reaction-evidence-transfer-01","v5-chem-reaction-evidence-transfer-02","v5-chem-reaction-evidence-transfer-03","v14-chemistry-reaction-evidence-051","v14-chemistry-reaction-evidence-052","v14-chemistry-reaction-evidence-053","v14-chemistry-reaction-evidence-054","v14-chemistry-reaction-evidence-055","v14-chemistry-reaction-evidence-056","v14-chemistry-reaction-evidence-057","v14-chemistry-reaction-evidence-058","v14-chemistry-reaction-evidence-059","v14-chemistry-reaction-evidence-060","v14-chemistry-reaction-evidence-061","v14-chemistry-reaction-evidence-062","v14-chemistry-reaction-evidence-063","v14-chemistry-reaction-evidence-064","v14-chemistry-reaction-evidence-065","v14-chemistry-reaction-evidence-066","v14-chemistry-reaction-evidence-067","v14-chemistry-reaction-evidence-068","v14-chemistry-reaction-evidence-069","v14-chemistry-reaction-evidence-070","v14-chemistry-reaction-evidence-071","v14-chemistry-reaction-evidence-072","v14-chemistry-reaction-evidence-073","v14-chemistry-reaction-evidence-074","v14-chemistry-reaction-evidence-075"]},{"stage":"INTEGRATION","focus":"Combinar sinais, controles e conservação da matéria para justificar conclusões.","questionIds":["v5-chem-reaction-evidence-lock-01"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Recuperar a distinção entre pista, produto e prova em novos contextos.","questionIds":["v5-chem-reaction-evidence-review-01","v5-chem-reaction-evidence-review-02","v5-chem-reaction-evidence-review-03","v5-chem-reaction-evidence-review-04","v5-chem-reaction-evidence-review-05","v5-chem-reaction-evidence-review-06","v5-chem-reaction-evidence-review-07"]}],"micro_explanations":[{"trigger":"OBSERVATION_VS_INFERENCE","text":"“Vi bolhas” é observação; “formou-se um produto” é inferência que precisa de evidência."},{"trigger":"ALTERNATIVE_PHYSICAL_CAUSE","text":"Ebulição, gás dissolvido e mistura de pigmentos podem explicar alguns sinais sem uma reação nova."},{"trigger":"NEW_SUBSTANCE","text":"A evidência mais importante é que uma ou mais substâncias diferentes foram formadas."},{"trigger":"CONTROL_COMPARISON","text":"Controles nas mesmas condições mostram se a mudança dependeu da interação entre os reagentes."},{"trigger":"MATTER_CONSERVATION_BOUNDARY","text":"Em recipiente aberto, gás que escapa deixa de ser contado pela balança local; a matéria não desaparece."},{"trigger":"CLAIM_SCOPE","text":"A conclusão deve ser tão forte quanto os dados, sem nomear produtos que não foram identificados."}],"remediations":[{"id":"SIGN_IS_NOT_PROOF","misconception":"BOLHA_COR_OU_TEMPERATURA_COMO_PROVA","prompt":"Liste uma causa física para o sinal observado e compare-a com a hipótese de reação."},{"id":"OBSERVATION_INFERENCE","misconception":"OBSERVACAO_COMO_CONCLUSAO","prompt":"Separe a frase em dado observado, hipótese e informação que falta para testar a hipótese."},{"id":"CONTROL_DESIGN","misconception":"CONTROLE_AUSENTE","prompt":"Descreva como cada reagente se comportaria sozinho nas mesmas condições da mistura."},{"id":"OPEN_SYSTEM_MASS","misconception":"MATERIA_DESTRUIDA","prompt":"Desenhe a fronteira do sistema medido e identifique se algum gás saiu ou entrou."},{"id":"PRODUCT_IDENTITY","misconception":"PRODUTO_NAO_IDENTIFICADO","prompt":"Compare uma propriedade do produto com as propriedades conhecidas dos reagentes antes de nomeá-lo."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Chemistry 2e, Section 1.3: Physical and Chemical Properties","publisher":"OpenStax","url":"https://openstax.org/books/chemistry-2e/pages/1-3-physical-and-chemical-properties","accessedOn":"2026-10-13","supports":["Mudanças físicas alteram estado ou propriedades sem alterar a identidade química.","Uma mudança química produz matéria diferente da presente antes da mudança."],"use":"Conferência conceitual; questões e explicações do pacote são autorais."},{"title":"Chemistry 2e, Section 1.2: Phases and Classification of Matter","publisher":"OpenStax","url":"https://openstax.org/books/chemistry-2e/pages/1-2-phases-and-classification-of-matter","accessedOn":"2026-10-13","supports":["A matéria total se conserva em mudanças químicas e físicas; a medição pode não incluir matéria que saiu do sistema."],"use":"Conferência da explicação sobre conservação da matéria e fronteira de sistemas abertos."},{"title":"Lesson 6.3: Forming a Precipitate","publisher":"American Chemical Society","url":"https://www.acs.org/middleschoolchemistry/lessonplans/chapter6/lesson3.html","accessedOn":"2026-10-13","supports":["A comparação controlada das propriedades do precipitado e dos reagentes pode confirmar a formação de substância diferente."],"use":"Referência didática para uso de controles e comparação de propriedades; texto e atividades do pacote são autorais."},{"title":"Lesson 3.5: Different Substances React Differently","publisher":"American Chemical Society","url":"https://www.acs.org/education/resources/k-8/inquiryinaction/fifth-grade/chapter-3/different-substances-react-differently.html","accessedOn":"2026-10-13","supports":["Gás, mudança de cor, temperatura e precipitado são evidências possíveis de reação, interpretadas em contexto."],"use":"Conferência das pistas observáveis e dos exemplos; não é fonte de alinhamento BNCC para este pacote."}],"copyright_note":"Questões, cenários, explicações e dados foram escritos para este pacote. As fontes conferem conceitos; alinhamento curricular oficial e revisão pedagógica humana permanecem pendentes. Lote V14 autoral com 100 questões e revisão pedagógica pendente; publicação mantida em STAGING.","objective":"Distinguir mudanças físicas de transformações químicas e justificar conclusões sobre formação de novas substâncias com evidências, controles e explicações alternativas.","common_mistake":"Tratar bolhas, cor, temperatura ou mudança de estado como prova automática, sem considerar controles, produtos e explicações físicas alternativas.","estimated_minutes":22}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 14
     and metadata->>'content_id' = 'v14-chemistry-reaction-evidence' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-chem-reaction-evidence-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"SUGAR_DISSOLUTION_RECOVERY","statement":"Açúcar é misturado à água e deixa de ser visível. Depois, a água evapora e cristais de açúcar aparecem no recipiente. Qual conclusão é mais compatível com as observações?","options":["O açúcar se dissolveu e voltou a cristalizar; não há evidência de uma substância nova.","O açúcar reagiu porque desapareceu da vista.","A evaporação transformou açúcar em água.","Os cristais provam que uma reação ocorreu durante a dissolução."],"correctAnswer":"O açúcar se dissolveu e voltou a cristalizar; não há evidência de uma substância nova.","explanation":"A dissolução dispersa partículas na água, e a evaporação permite recuperar o açúcar. Mudança de aparência, sem mudança de composição, é física.","errorFocus":"Interpretar o desaparecimento visual durante dissolução como formação de outra substância.","hint":"Pergunte se a composição mudou ou se as mesmas partículas apenas se dispersaram e puderam ser recuperadas.","misconceptions":{"O açúcar reagiu porque desapareceu da vista.":["INTERPRETAR_O_DESAPARECIMENTO_VISUAL_DURANTE_DISSOLU_O_COMO_FORMA_O_DE_OUTRA_SUBST_NCIA"]},"position":1},{"id":"v5-chem-reaction-evidence-probe-02","purpose":"PROBE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"DYE_MIXTURE_CHROMATOGRAPHY","statement":"Duas soluções de corantes são misturadas e ficam roxas. Uma análise posterior separa novamente os mesmos dois corantes, sem detectar produtos diferentes. O que a mudança de cor permite concluir?","options":["A cor roxa prova que surgiu uma substância nova.","Sozinha, não demonstra reação; os dados mostram uma mistura física dos corantes originais.","A análise não importa, pois toda mistura de soluções é reação.","Os corantes deixaram de existir porque a cor mudou."],"correctAnswer":"Sozinha, não demonstra reação; os dados mostram uma mistura física dos corantes originais.","explanation":"A cor observada mudou, mas a análise recuperou os mesmos componentes. Uma mudança de cor pode ser pista, não prova isolada de reação.","errorFocus":"Tomar qualquer mudança de cor como prova conclusiva de transformação química.","hint":"Separe a observação visual dos dados sobre quais substâncias estavam presentes antes e depois.","misconceptions":{"A cor roxa prova que surgiu uma substância nova.":["TOMAR_QUALQUER_MUDAN_A_DE_COR_COMO_PROVA_CONCLUSIVA_DE_TRANSFORMA_O_QU_MICA"]},"position":2},{"id":"v5-chem-reaction-evidence-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"COLORLESS_SOLUTIONS_CONTROLLED_PRECIPITATE","statement":"Duas soluções transparentes formam um sólido ao serem combinadas. Em ensaios de controle, cada solução permanece transparente quando submetida sozinha às mesmas condições. Qual interpretação é mais forte?","options":["A transparência inicial prova que as soluções eram a mesma substância.","O sólido é necessariamente um reagente que já estava visível.","A formação do sólido, ausente nos controles, sustenta a hipótese de uma nova substância insolúvel.","Nenhuma conclusão é possível mesmo com controles e produto diferente."],"correctAnswer":"A formação do sólido, ausente nos controles, sustenta a hipótese de uma nova substância insolúvel.","explanation":"O sólido aparece apenas quando os reagentes interagem. Um precipitado com propriedades diferentes das soluções é evidência convergente de formação de produto.","errorFocus":"Ignorar controles ou afirmar uma causa sem comparar os reagentes isolados.","hint":"Compare o resultado da mistura com cada controle e procure uma propriedade do sólido diferente das soluções iniciais.","misconceptions":{"A transparência inicial prova que as soluções eram a mesma substância.":["IGNORAR_CONTROLES_OU_AFIRMAR_UMA_CAUSA_SEM_COMPARAR_OS_REAGENTES_ISOLADOS"]},"position":1},{"id":"v5-chem-reaction-evidence-practice-02","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"DISTILLATION_WATER_IDENTITY","statement":"Durante uma demonstração, água líquida ferve, o vapor passa por um condensador e volta a ser coletado como líquido. Qual afirmação descreve melhor o processo observado?","options":["A água se decompôs porque apareceram bolhas.","O condensador criou uma substância nova ao resfriar o vapor.","A ebulição prova que os átomos de hidrogênio desapareceram.","A água mudou de estado e voltou ao líquido; isso, por si só, não indica uma reação química."],"correctAnswer":"A água mudou de estado e voltou ao líquido; isso, por si só, não indica uma reação química.","explanation":"Ebulição e condensação são mudanças de estado. Se a substância recuperada continua sendo água, não se identificou mudança química.","errorFocus":"Confundir ebulição e condensação com reação por causa da formação de vapor.","hint":"Verifique se houve apenas mudança de estado ou se os produtos têm composição diferente da água.","misconceptions":{"A água se decompôs porque apareceram bolhas.":["CONFUNDIR_EBULI_O_E_CONDENSA_O_COM_REA_O_POR_CAUSA_DA_FORMA_O_DE_VAPOR"]},"position":2},{"id":"v5-chem-reaction-evidence-practice-03","purpose":"PRACTICE","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"REACTION_EVIDENCE_CONVERGING_TABLE","statement":"Três equipes analisam amostras. Na A, um líquido aquecido produz bolhas; na B, uma mistura forma um sólido que não aparece nos controles; na C, duas tintas apenas se misturam. Qual resultado oferece a evidência mais forte de reação?","options":["A equipe B, porque o sólido novo aparece após a interação e não nos controles.","A equipe A, pois qualquer bolha prova reação.","A equipe C, pois qualquer cor final diferente prova produto químico.","As três equipes têm evidência igualmente conclusiva."],"correctAnswer":"A equipe B, porque o sólido novo aparece após a interação e não nos controles.","explanation":"Bolhas podem vir de ebulição, e misturar pigmentos pode alterar a cor sem criar substância. Um sólido novo, ausente em controles comparáveis, sustenta melhor a hipótese química.","errorFocus":"Escolher a pista mais visível sem considerar explicações alternativas e controles.","hint":"Procure uma mudança que dependa da interação dos reagentes e compare com controles adequados.","misconceptions":{"A equipe A, pois qualquer bolha prova reação.":["ESCOLHER_A_PISTA_MAIS_VIS_VEL_SEM_CONSIDERAR_EXPLICA_ES_ALTERNATIVAS_E_CONTROLES"]},"position":3},{"id":"v5-chem-reaction-evidence-transfer-01","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"BREAD_FERMENTATION_BLANK_CONTROL","statement":"Em dois frascos com a mesma solução açucarada, apenas aquele que recebeu levedura produz gás. A análise identifica dióxido de carbono e etanol nesse frasco; o controle sem levedura não apresenta esses produtos. Qual conclusão é sustentada?","options":["Apenas ocorreu ebulição, embora o frasco não tenha sido aquecido.","Os dados apoiam uma transformação química associada à fermentação, com produtos diferentes dos reagentes.","O açúcar mudou de estado e por isso virou dióxido de carbono.","O controle prova que qualquer gás em líquido é produto químico."],"correctAnswer":"Os dados apoiam uma transformação química associada à fermentação, com produtos diferentes dos reagentes.","explanation":"Produtos identificados apenas no sistema com levedura e açúcar sustentam a formação de novas substâncias. O controle ajuda a excluir produção espontânea ou causada pelo recipiente.","errorFocus":"Confundir a observação de gás com a explicação do processo sem usar o controle e a análise dos produtos.","hint":"Compare os produtos do frasco com levedura ao controle e identifique o que mudou na composição.","misconceptions":{"Apenas ocorreu ebulição, embora o frasco não tenha sido aquecido.":["CONFUNDIR_A_OBSERVA_O_DE_G_S_COM_A_EXPLICA_O_DO_PROCESSO_SEM_USAR_O_CONTROLE_E_A_AN_LISE_DOS_PRODUTOS"]},"position":1},{"id":"v5-chem-reaction-evidence-transfer-02","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"SODA_BOTTLE_PRESSURE_RELEASE","statement":"Ao abrir uma garrafa de água gaseificada, surgem bolhas e o som de liberação de gás. A quantidade de dióxido de carbono dissolvido diminui, mas não há reagentes novos nem produtos detectados. Qual interpretação é adequada?","options":["O dióxido de carbono foi produzido por uma reação porque se tornou visível.","A água se decompôs em gás e líquido ao abrir a tampa.","O gás dissolvido está saindo da solução após a queda de pressão; as bolhas não demonstram uma reação nova.","Toda liberação de gás transforma a bebida em outra substância."],"correctAnswer":"O gás dissolvido está saindo da solução após a queda de pressão; as bolhas não demonstram uma reação nova.","explanation":"A abertura altera a pressão e favorece a saída do dióxido de carbono que já estava dissolvido. A observação de bolhas não basta para afirmar que houve reação.","errorFocus":"Supor que um gás observado necessariamente se formou durante o evento.","hint":"Pergunte se o gás foi produzido por reagentes ou se já estava dissolvido e apenas escapou.","misconceptions":{"O dióxido de carbono foi produzido por uma reação porque se tornou visível.":["SUPOR_QUE_UM_G_S_OBSERVADO_NECESSARIAMENTE_SE_FORMOU_DURANTE_O_EVENTO"]},"position":2},{"id":"v5-chem-reaction-evidence-transfer-03","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"IRON_CORROSION_DRY_MOIST_CONTROLS","statement":"Três peças iguais de ferro ficam em condições distintas: ar seco, água sem contato com ar e ar úmido. Apenas na última aparece uma camada de ferrugem; a inspeção confirma material com propriedades diferentes do ferro. O que os dados sustentam?","options":["A ferrugem é somente água que mudou de estado sobre o ferro.","O controle em ar seco prova que o ferro nunca reage com oxigênio.","A camada confirma que a massa de ferro foi destruída.","A interação do ferro com água e oxigênio favoreceu uma transformação química; os controles ajudam a identificar as condições necessárias."],"correctAnswer":"A interação do ferro com água e oxigênio favoreceu uma transformação química; os controles ajudam a identificar as condições necessárias.","explanation":"O produto com propriedades diferentes aparece na condição que reúne umidade e oxigênio. Comparar controles permite avaliar quais condições acompanham a corrosão.","errorFocus":"Atribuir ferrugem a uma única condição sem considerar a comparação controlada.","hint":"Compare as condições dos três recipientes e relacione o produto observado às condições que ocorreram juntas.","misconceptions":{"A ferrugem é somente água que mudou de estado sobre o ferro.":["ATRIBUIR_FERRUGEM_A_UMA_NICA_CONDI_O_SEM_CONSIDERAR_A_COMPARA_O_CONTROLADA"]},"position":3},{"id":"v5-chem-reaction-evidence-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"DISTINGUISH","contextFamily":"CANDLE_MELTING_AND_COMBUSTION","statement":"Ao acender uma vela, a cera próxima ao pavio derrete e a chama libera gases. Qual análise separa corretamente os dois fenômenos?","options":["Derreter a cera é mudança física; a combustão da cera vaporizada forma substâncias diferentes e é química.","Os dois fenômenos são físicos porque ocorrem na mesma vela.","Os dois são reações porque a vela muda de forma.","A chama é física, mas derreter a cera é uma reação química."],"correctAnswer":"Derreter a cera é mudança física; a combustão da cera vaporizada forma substâncias diferentes e é química.","explanation":"A cera líquida continua sendo cera, então a fusão é física. Na combustão, a cera reage com oxigênio e origina produtos com composição diferente.","errorFocus":"Classificar processos simultâneos como se todos tivessem a mesma natureza.","hint":"Analise cada etapa separadamente: mudança de estado e formação de produtos são evidências diferentes.","misconceptions":{"Os dois fenômenos são físicos porque ocorrem na mesma vela.":["CLASSIFICAR_PROCESSOS_SIMULT_NEOS_COMO_SE_TODOS_TIVESSEM_A_MESMA_NATUREZA"]},"position":1},{"id":"v5-chem-reaction-evidence-review-01","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"OPEN_REACTOR_ESCAPING_GAS_MASS","statement":"Uma reação que libera gás ocorre em um frasco aberto sobre uma balança. A massa indicada diminui, mas o gás que sai é coletado em outro recipiente e também pesado. Como interpretar o resultado?","options":["A reação destruiu matéria, pois o frasco ficou mais leve.","A leitura do frasco diminui porque parte da matéria saiu; ao incluir o gás coletado, a massa total se conserva.","A massa do gás não conta porque ele deixou o recipiente.","A queda na balança prova que não houve reação química."],"correctAnswer":"A leitura do frasco diminui porque parte da matéria saiu; ao incluir o gás coletado, a massa total se conserva.","explanation":"A balança do frasco aberto mede apenas o que permaneceu nele. Somando o gás que escapou, o sistema ampliado inclui a matéria transferida e conserva a massa.","errorFocus":"Confundir a fronteira do sistema medido com a quantidade total de matéria.","hint":"Defina o que está dentro do sistema da balança e inclua a matéria que saiu ao comparar o total.","misconceptions":{"A reação destruiu matéria, pois o frasco ficou mais leve.":["CONFUNDIR_A_FRONTEIRA_DO_SISTEMA_MEDIDO_COM_A_QUANTIDADE_TOTAL_DE_MAT_RIA"]},"position":1},{"id":"v5-chem-reaction-evidence-review-02","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"APPLE_BROWNING_AFTER_CUT","statement":"Uma maçã cortada escurece após ficar exposta ao ar. Qual dado favorece a interpretação de transformação química, em vez de simples mudança de forma?","options":["O corte aumentou a área exposta, portanto nenhuma mudança química pode ocorrer.","A cor prova sozinha que uma substância específica foi formada.","A exposição ao oxigênio acompanha a formação de compostos escuros diferentes dos presentes na polpa fresca.","A maçã perdeu todos os átomos de sua superfície."],"correctAnswer":"A exposição ao oxigênio acompanha a formação de compostos escuros diferentes dos presentes na polpa fresca.","explanation":"O corte é uma mudança física, mas o escurecimento envolve reações com o oxigênio e a formação de compostos diferentes. A cor é uma pista interpretada junto da evidência sobre os produtos.","errorFocus":"Confundir o corte físico com os processos químicos posteriores ou usar cor como prova isolada.","hint":"Separe o efeito mecânico do corte das mudanças que ocorreram depois da exposição ao ar.","misconceptions":{"O corte aumentou a área exposta, portanto nenhuma mudança química pode ocorrer.":["CONFUNDIR_O_CORTE_F_SICO_COM_OS_PROCESSOS_QU_MICOS_POSTERIORES_OU_USAR_COR_COMO_PROVA_ISOLADA"]},"position":2},{"id":"v5-chem-reaction-evidence-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"REUSABLE_HANDWARMER_CRYSTALLIZATION","statement":"Em um aquecedor reutilizável, uma solução supersaturada cristaliza após um gatilho e libera calor. Depois, o sólido pode voltar a se dissolver quando aquecido, sem formar outros produtos. Qual conclusão é mais compatível?","options":["A liberação de calor comprova que novas substâncias foram formadas.","O cristal é necessariamente um produto químico porque é sólido.","O processo destruiu a solução e criou matéria do recipiente.","A cristalização é uma mudança física de organização e estado; a liberação de calor não prova, sozinha, reação."],"correctAnswer":"A cristalização é uma mudança física de organização e estado; a liberação de calor não prova, sozinha, reação.","explanation":"A mesma substância pode cristalizar e depois se dissolver. Mudança térmica acompanha o processo, mas, sem mudança de composição, não basta para classificá-lo como reação.","errorFocus":"Tratar qualquer variação de temperatura ou formação de sólido como prova de reação.","hint":"Use a possibilidade de recuperar a mesma composição e procure evidência de produtos diferentes.","misconceptions":{"A liberação de calor comprova que novas substâncias foram formadas.":["TRATAR_QUALQUER_VARIA_O_DE_TEMPERATURA_OU_FORMA_O_DE_S_LIDO_COMO_PROVA_DE_REA_O"]},"position":3},{"id":"v5-chem-reaction-evidence-review-04","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"SEALED_REACTION_MASS_BALANCE","statement":"Dois reagentes são misturados dentro de um recipiente selado. Há mudança de cor e formação de um sólido; a massa total antes e depois permanece igual. Qual afirmação concilia as observações?","options":["Uma reação pode formar substâncias novas e conservar a massa total em sistema fechado.","A massa igual prova que nenhuma reação aconteceu.","A cor mudou, então os átomos deixaram de ser conservados.","O sólido formado precisa ter vindo de fora do recipiente."],"correctAnswer":"Uma reação pode formar substâncias novas e conservar a massa total em sistema fechado.","explanation":"Uma reação reorganiza átomos sem criar ou destruir matéria. A massa total do sistema fechado pode permanecer igual enquanto as substâncias mudam.","errorFocus":"Interpretar conservação da massa como ausência de transformação química.","hint":"Separe conservação dos átomos e da massa da identidade das substâncias antes e depois.","misconceptions":{"A massa igual prova que nenhuma reação aconteceu.":["INTERPRETAR_CONSERVA_O_DA_MASSA_COMO_AUS_NCIA_DE_TRANSFORMA_O_QU_MICA"]},"position":4},{"id":"v5-chem-reaction-evidence-review-05","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"INDICATOR_COLOR_CONTROLLED_PH","statement":"Um indicador muda de cor quando é adicionado a uma solução. Para avaliar se a amostra também sofreu outra reação, qual informação é mais útil?","options":["A cor, sozinha, identifica todos os produtos formados.","Comparar a amostra a um controle e analisar se apareceram produtos diferentes, além da resposta de cor do indicador.","O indicador sempre reage com qualquer substância da solução.","Nenhum controle é necessário porque a cor é uma prova direta."],"correctAnswer":"Comparar a amostra a um controle e analisar se apareceram produtos diferentes, além da resposta de cor do indicador.","explanation":"A cor do indicador responde às condições químicas da solução, mas não descreve por si só toda a composição da amostra. Controle e análise de produtos delimitam a conclusão.","errorFocus":"Atribuir ao material analisado toda mudança de cor causada pelo próprio indicador.","hint":"Considere o papel do indicador e compare a amostra com um controle sem a mudança investigada.","misconceptions":{"A cor, sozinha, identifica todos os produtos formados.":["ATRIBUIR_AO_MATERIAL_ANALISADO_TODA_MUDAN_A_DE_COR_CAUSADA_PELO_PR_PRIO_INDICADOR"]},"position":5},{"id":"v5-chem-reaction-evidence-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"DESIGN","contextFamily":"FAIR_CONTROL_FOR_COLOR_CHANGE","statement":"Uma estudante quer testar se duas soluções reagem para formar um produto colorido. Qual desenho oferece a comparação mais informativa?","options":["Misturar volumes diferentes e comparar com uma solução de outro recipiente.","Testar somente a mistura e concluir a partir da primeira cor observada.","Manter volumes, temperatura e recipiente iguais, testar cada solução isolada e a mistura, repetir e comparar a composição final.","Alterar temperatura e iluminação ao mesmo tempo para acelerar a mudança."],"correctAnswer":"Manter volumes, temperatura e recipiente iguais, testar cada solução isolada e a mistura, repetir e comparar a composição final.","explanation":"Controles isolam o efeito da interação entre as soluções. Repetições e condições constantes ajudam a separar produto novo de cor inicial, iluminação ou aquecimento.","errorFocus":"Mudar várias condições ao mesmo tempo e atribuir o resultado a uma única causa.","hint":"Mantenha as condições constantes e inclua controles de cada reagente isolado.","misconceptions":{"Misturar volumes diferentes e comparar com uma solução de outro recipiente.":["MUDAR_V_RIAS_CONDI_ES_AO_MESMO_TEMPO_E_ATRIBUIR_O_RESULTADO_A_UMA_NICA_CAUSA"]},"position":6},{"id":"v5-chem-reaction-evidence-review-07","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"JUSTIFY","contextFamily":"CLAIM_EVIDENCE_REASONING_FINAL","statement":"Um relatório afirma: “Houve reação química porque a mistura borbulhou”. Qual revisão transforma a afirmação em uma conclusão melhor justificada?","options":["Manter a frase, pois bolhas são prova universal de reação.","Trocar “borbulhou” por “mudou de cor” e manter a mesma conclusão.","Concluir que ocorreu ebulição sem verificar a temperatura.","Registrar as bolhas como observação, comparar com controles e buscar evidência de produto novo antes de concluir."],"correctAnswer":"Registrar as bolhas como observação, comparar com controles e buscar evidência de produto novo antes de concluir.","explanation":"Uma conclusão científica distingue observação de inferência e avalia alternativas, como gás dissolvido ou ebulição. Evidência de produto novo e controles fortalecem a afirmação.","errorFocus":"Apresentar uma inferência como fato sem mostrar dados que a sustentem.","hint":"Escreva separadamente o que foi observado, a hipótese e o teste que poderia diferenciá-la de alternativas.","misconceptions":{"Manter a frase, pois bolhas são prova universal de reação.":["APRESENTAR_UMA_INFER_NCIA_COMO_FATO_SEM_MOSTRAR_DADOS_QUE_A_SUSTENTEM"]},"position":7},{"id":"v14-chemistry-reaction-evidence-001","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"V14_CHEMISTRY_REACTION_PRECIPITATE_01","statement":"Duas soluções incolores são misturadas e formam um sólido branco. Em um controle, cada solução permanece líquida quando testada separadamente. Que evidência torna a hipótese de reação mais forte?","options":["O sólido aparece na mistura e não nos controles, indicando um produto com propriedades diferentes.","A cor branca prova a reação mesmo sem comparar controles.","O sólido estava necessariamente escondido em uma das soluções.","Nenhuma observação de produto pode apoiar uma hipótese química."],"correctAnswer":"O sólido aparece na mistura e não nos controles, indicando um produto com propriedades diferentes.","explanation":"A resposta interpreta uma evidência química sem ignorar controles, composição ou limites do sistema. Compare o produto com os reagentes e use controles realizados nas mesmas condições.","hint":"Separe o que foi observado da explicação e procure controles que testem alternativas.","errorFocus":"CHEMISTRY_REACTION_EVIDENCE_SCOPE","misconceptions":{"A cor branca prova a reação mesmo sem comparar controles.":["CHEMISTRY_REACTION_EVIDENCE_SCOPE"]},"position":3},{"id":"v14-chemistry-reaction-evidence-002","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"V14_CHEMISTRY_REACTION_PRECIPITATE_02","statement":"Duas soluções incolores são misturadas e formam um sólido branco. Em um controle, cada solução permanece líquida quando testada separadamente. Qual critério deve orientar a análise?","options":["A cor branca prova a reação mesmo sem comparar controles.","Use Compare o produto com os reagentes e use controles realizados nas mesmas condições.","O sólido estava necessariamente escondido em uma das soluções.","Nenhuma observação de produto pode apoiar uma hipótese química."],"correctAnswer":"Use Compare o produto com os reagentes e use controles realizados nas mesmas condições.","explanation":"A resposta interpreta uma evidência química sem ignorar controles, composição ou limites do sistema. Compare o produto com os reagentes e use controles realizados nas mesmas condições.","hint":"Separe o que foi observado da explicação e procure controles que testem alternativas.","errorFocus":"CHEMISTRY_REACTION_EVIDENCE_SCOPE","misconceptions":{"A cor branca prova a reação mesmo sem comparar controles.":["CHEMISTRY_REACTION_EVIDENCE_SCOPE"]},"position":4},{"id":"v14-chemistry-reaction-evidence-003","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"V14_CHEMISTRY_REACTION_PRECIPITATE_03","statement":"Duas soluções incolores são misturadas e formam um sólido branco. Em um controle, cada solução permanece líquida quando testada separadamente. Como transferir esse raciocínio para outro caso?","options":["A cor branca prova a reação mesmo sem comparar controles.","O sólido estava necessariamente escondido em uma das soluções.","Avalie outro experimento em que um produto surge somente depois da combinação dos reagentes.","Nenhuma observação de produto pode apoiar uma hipótese química."],"correctAnswer":"Avalie outro experimento em que um produto surge somente depois da combinação dos reagentes.","explanation":"A resposta interpreta uma evidência química sem ignorar controles, composição ou limites do sistema. Compare o produto com os reagentes e use controles realizados nas mesmas condições.","hint":"Separe o que foi observado da explicação e procure controles que testem alternativas.","errorFocus":"CHEMISTRY_REACTION_EVIDENCE_SCOPE","misconceptions":{"A cor branca prova a reação mesmo sem comparar controles.":["CHEMISTRY_REACTION_EVIDENCE_SCOPE"]},"position":5},{"id":"v14-chemistry-reaction-evidence-004","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"V14_CHEMISTRY_REACTION_PRECIPITATE_04","statement":"Duas soluções incolores são misturadas e formam um sólido branco. Em um controle, cada solução permanece líquida quando testada separadamente. Qual conclusão deve ser evitada?","options":["A cor branca prova a reação mesmo sem comparar controles.","O sólido estava necessariamente escondido em uma das soluções.","Nenhuma observação de produto pode apoiar uma hipótese química.","Evite dizer que qualquer turvação prova uma reação sem verificar o controle."],"correctAnswer":"Evite dizer que qualquer turvação prova uma reação sem verificar o controle.","explanation":"A resposta interpreta uma evidência química sem ignorar controles, composição ou limites do sistema. Compare o produto com os reagentes e use controles realizados nas mesmas condições.","hint":"Separe o que foi observado da explicação e procure controles que testem alternativas.","errorFocus":"CHEMISTRY_REACTION_EVIDENCE_SCOPE","misconceptions":{"A cor branca prova a reação mesmo sem comparar controles.":["CHEMISTRY_REACTION_EVIDENCE_SCOPE"]},"position":6},{"id":"v14-chemistry-reaction-evidence-005","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"V14_CHEMISTRY_REACTION_PRECIPITATE_05","statement":"Duas soluções incolores são misturadas e formam um sólido branco. Em um controle, cada solução permanece líquida quando testada separadamente. Que evidência deve ser conferida primeiro?","options":["Confira sólido formado, controles e propriedades das soluções.","A cor branca prova a reação mesmo sem comparar controles.","O sólido estava necessariamente escondido em uma das soluções.","Nenhuma observação de produto pode apoiar uma hipótese química."],"correctAnswer":"Confira sólido formado, controles e propriedades das soluções.","explanation":"A resposta interpreta uma evidência química sem ignorar controles, composição ou limites do sistema. Compare o produto com os reagentes e use controles realizados nas mesmas condições.","hint":"Separe o que foi observado da explicação e procure controles que testem alternativas.","errorFocus":"CHEMISTRY_REACTION_EVIDENCE_SCOPE","misconceptions":{"A cor branca prova a reação mesmo sem comparar controles.":["CHEMISTRY_REACTION_EVIDENCE_SCOPE"]},"position":7},{"id":"v14-chemistry-reaction-evidence-006","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"DISTINGUISH","contextFamily":"V14_CHEMISTRY_REACTION_PRECIPITATE_06","statement":"Duas soluções incolores são misturadas e formam um sólido branco. Em um controle, cada solução permanece líquida quando testada separadamente. Qual é o próximo passo mais cuidadoso?","options":["A cor branca prova a reação mesmo sem comparar controles.","repetir a mistura e caracterizar o sólido com uma propriedade observável","O sólido estava necessariamente escondido em uma das soluções.","Nenhuma observação de produto pode apoiar uma hipótese química."],"correctAnswer":"repetir a mistura e caracterizar o sólido com uma propriedade observável","explanation":"A resposta interpreta uma evidência química sem ignorar controles, composição ou limites do sistema. Compare o produto com os reagentes e use controles realizados nas mesmas condições.","hint":"Separe o que foi observado da explicação e procure controles que testem alternativas.","errorFocus":"CHEMISTRY_REACTION_EVIDENCE_SCOPE","misconceptions":{"A cor branca prova a reação mesmo sem comparar controles.":["CHEMISTRY_REACTION_EVIDENCE_SCOPE"]},"position":8},{"id":"v14-chemistry-reaction-evidence-007","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"V14_CHEMISTRY_REACTION_PRECIPITATE_07","statement":"Duas soluções incolores são misturadas e formam um sólido branco. Em um controle, cada solução permanece líquida quando testada separadamente. Qual limite deve aparecer na resposta?","options":["A cor branca prova a reação mesmo sem comparar controles.","O sólido estava necessariamente escondido em uma das soluções.","Mantenha a conclusão ligada a a evidência disponível e as condições do ensaio.","Nenhuma observação de produto pode apoiar uma hipótese química."],"correctAnswer":"Mantenha a conclusão ligada a a evidência disponível e as condições do ensaio.","explanation":"A resposta interpreta uma evidência química sem ignorar controles, composição ou limites do sistema. Compare o produto com os reagentes e use controles realizados nas mesmas condições.","hint":"Sep